  document.getElementById('userPopup').style.display = 'block';
  mostrarLogin();
}

function cerrarPopup() {
  document.getElementById('userPopup').style.display = 'none';
}

function mostrarLogin() {
  document.getElementById('loginForm').style.display = 'block';
  document.getElementById('registerForm').style.display = 'none';
  document.getElementById('popupTitle').textContent = 'Iniciar Sesión';
}

function mostrarRegistro() {
  document.getElementById('loginForm').style.display = 'none';
  document.getElementById('registerForm').style.display = 'block';
  document.getElementById('popupTitle').textContent = 'Crear Cuenta';
}

function iniciarSesion() {
  const email = document.getElementById('login_email').value;
  const password = document.getElementById('login_password').value;

  if (!email || !password) {
    alert("Por favor completa todos los campos");
    return;
  }
  alert("Inicio de sesión (funcionalidad en desarrollo)");
  cerrarPopup();
}

async function registrarUsuario() {
  const nombre = document.getElementById('reg_nombre').value;
  const email = document.getElementById('reg_email').value;
  const password = document.getElementById('reg_password').value;

  if (!nombre || !email || !password) {
    alert("Por favor completa todos los campos");
    return;
  }

  try {
    await frappe.call({
      method: 'frappe.client.insert',
      args: {
        doc: {
          doctype: "Usuario",
          nombre: nombre,
          email: email,
          password: password
        }
      }
    });
    alert("¡Cuenta creada correctamente!");
    mostrarLogin();
  } catch (e) {
    alert("Error: " + (e.message || e));
  }
}

// Cargar todo al iniciar la página
frappe.ready(() => {
