});

async function cargarCategorias() {
  const res = await frappe.call({
    method: 'frappe.client.get_list',
    args: {
      doctype: 'Categoria',
      fields: ['name', 'nombre']
    }
  });

  let html = '';
  res.message.forEach(cat => {
    html += `
      <div class="col-md-4 col-sm-6 mb-4">
        <div class="card h-100 text-center cursor-pointer" onclick="mostrarComponentes('${cat.name}', '${cat.nombre}')">
          <div class="card-body">
            <h5 class="card-title">${cat.nombre}</h5>
            <p class="text-muted">Ver componentes →</p>
          </div>
        </div>
      </div>`;
  });

  document.getElementById('categorias-container').innerHTML = html;
}

async function mostrarComponentes(cat_name, cat_nombre) {
  document.getElementById('categorias-container').style.display = 'none';
  document.getElementById('componentes-section').style.display = 'block';
  document.getElementById('categoria-titulo').textContent = `Componentes - ${cat_nombre}`;

  const res = await frappe.call({
    method: 'frappe.client.get_list',
    args: {
      doctype: 'Componente',
      filters: { id_categoria: cat_name },
      fields: ['name', 'nombre', 'precio', 'estado', 'foto']
    }
  });

  let html = '';
  res.message.forEach(comp => {
    html += `
      <div class="col-md-3 col-sm-6 mb-4">
        <div class="card h-100">
          ${comp.foto ? `<img src="${comp.foto}" class="card-img-top" style="height: 180px; object-fit: cover;">` : ''}
          <div class="card-body">
            <h6 class="card-title">${comp.nombre}</h6>
            <p class="text-success fw-bold">${comp.precio || 0} €</p>
            <p class="text-muted small">${comp.estado || ''}</p>
            <button class="btn btn-primary btn-sm w-100">Añadir al carrito</button>
          </div>
        </div>
      </div>`;
  });

  document.getElementById('componentes-container').innerHTML = html || '<p class="text-center">No hay componentes en esta categoría.</p>';
}

function volverACategorias() {
  document.getElementById('categorias-container').style.display = 'flex';
